    [19028] = { "При застосуванні {1}% від всієї отриманої вами шкоди буде натомість перенаправлено на вашого біса, пустотника, сукуба, інкуба або скверногончу. Окрім того, демон і його володар завдаватимуть на {2}% більше шкоди. Триває допоки демон активний.[ Не можна використовувати, поки активна \"Метаморфоза\".", { 1, 2 }, "of all damage taken by the caster is tak" }, -- Soul Link
    [23785] = { "Чорнокнижник і викликаний демон отримують ефект, поки демон активний. Біс: шкода від вогню збільшується на {1}%. Пустотник: отримувана фізична шкода зменшується на {2}%. Сукуб або інкуб: шкода від тіні збільшується на {3}%. Мисливець Скверни: отримувана магічна шкода зменшується на {4}%.", { 1, 2, 3, 4 }, "Grants both the Warlock and the summoned" }, -- Master Demonologist
    [403511] = { "Збільшує обсяг висмоктаного здоров'я або шкоду від «Витягування життя», «Витягування душі» та «Виснаження» на {1}%.", { 1 }, "Increases health drained or damage done" }, -- Improved Drains
