    [426316] = { "«Пожежа» збільшує всю вашу шкоду від тіні на {1}% протягом {2} с, а «Опік тінню» збільшує всю шкоду від вогню на {3}% протягом {4} с. Крім того, «Пожежа» з імовірністю {5}% не поглинає «Жертовний вогонь», а «Опік тінню» з імовірністю {6}% миттєво повертає уламок душі.", { 1, 2, 3, 4, 5, 6 }, "Hitting an enemy with Conflagrate increa" }, -- Shadow and Flame
    [427712] = { "Збільшує бонус шкоди від критичних ефектів «Псування», «Прокляття агонії», «Прокляття приречення», «Витягування душі», «Витягування життя», «Висмоктування життя» та «Виснаження» на {1}%.", { 1 }, "Increases the critical strike damage bon" }, -- Pandemic
