    [440870] = { "Зменшує час відновлення «Вогню душі» на {1}%. «Тіньова стріла» та «Пекучий біль» завдають на {3}% більше шкоди ворогам із запасом здоров'я менш ніж {2}%. Після їх застосування протягом {4} с час застосування «Вогню душі» зменшується на {5}%, і він не витрачає уламків душі.", { 1, 2, 3, 4, 5 }, "Reduces the cooldown of your Soul Fire s" }, -- Decimation
    [1225177] = { "Збільшує всю періодичну шкоду ваших заклять чорнокнижника на {1}%.", { 1 }, "Increases all periodic damage done by yo" }, -- Malediction
    [1225214] = { "Ваш улюбленець зцілюється на {1}% від усієї шкоди ваших заклять. Коли «Відвід життя» дає вам ману, викликаний демон отримує {2}% від її обсягу.", { 1, 2 }, "You heal your pet for" }, -- Demonic Energies
