    [1225220] = { "Зменшує всю отримувану шкоду на {1}%.", { 1 }, "Reduces all damage taken by" }, -- Molten Skin
    [1225228] = { "Проклинає ціль на {1} с: {2}% шкоди, яку ви завдаєте іншим цілям, також отримує проклята ціль. «Прокляття спустошення» діє лише на одну ціль. На цілі може діяти лише одне ваше прокляття цього типу.", { 1, 2, "1" }, "Afflicts the target for" }, -- Bane of Havoc
